// Command liveplaydemo exports the isolated T-039 causal live-play demo clips as
// versioned authoritative traces for the same-clock 2D prototype viewer.
//
// The clips are generated by the live-play physics in internal/liveplay; the
// initial release of each clip is a scripted fixture action and every later
// contact, deflection and control is simulated. Regenerate with:
//
//	make prototype
//
// or run this command directly:
//
//	go run ./cmd/liveplaydemo -out ../web/public/prototype
package main

import (
	"encoding/json"
	"flag"
	"fmt"
	"os"
	"path/filepath"

	"github.com/yigitarac/manageria/server/internal/liveplay"
)

// prototypeIndex is the manifest written beside the clips. It records the schema
// version and per-clip size so a missing or stale asset is easy to spot.
type prototypeIndex struct {
	SchemaVersion int            `json:"schemaVersion"`
	GeneratedBy   string         `json:"generatedBy"`
	Clips         []prototypeRef `json:"clips"`
}

type prototypeRef struct {
	Slug        string `json:"slug"`
	Label       string `json:"label"`
	Description string `json:"description"`
	FrameCount  int    `json:"frameCount"`
	EventCount  int    `json:"eventCount"`
	Bytes       int    `json:"bytes"`
}

func main() {
	out := flag.String("out", "../web/public/prototype", "output directory for the prototype clip JSON")
	fixture := flag.String("fixture", "", "write only the tiny real web-test fixture to this file and exit")
	flag.Parse()

	if *fixture != "" {
		trace, err := liveplay.PrototypeFixtureTrace()
		if err != nil {
			fatal(err)
		}
		raw, err := json.Marshal(trace)
		if err != nil {
			fatal(err)
		}
		if err := os.WriteFile(*fixture, raw, 0o644); err != nil {
			fatal(err)
		}
		fmt.Printf("fixture %s → %s (%d points, %d bytes)\n", trace.Slug, *fixture, len(trace.Points), len(raw))
		return
	}

	if err := os.MkdirAll(*out, 0o755); err != nil {
		fatal(err)
	}

	clips, err := liveplay.BuildPrototypeClips()
	if err != nil {
		fatal(err)
	}

	index := prototypeIndex{
		SchemaVersion: liveplay.TraceSchemaVersion,
		GeneratedBy:   "liveplaydemo",
	}
	total := 0
	for i := range clips {
		trace := &clips[i]
		raw, err := json.Marshal(trace)
		if err != nil {
			fatal(err)
		}
		path := filepath.Join(*out, trace.Slug+".json")
		if err := os.WriteFile(path, raw, 0o644); err != nil {
			fatal(err)
		}
		total += len(raw)
		index.Clips = append(index.Clips, prototypeRef{
			Slug:        trace.Slug,
			Label:       trace.Label,
			Description: trace.Description,
			FrameCount:  trace.FrameCount,
			EventCount:  trace.EventCount,
			Bytes:       len(raw),
		})
		fmt.Printf("%-24s %5d points %4d events %7d bytes  seed %d\n",
			trace.Slug, trace.FrameCount, trace.EventCount, len(raw), trace.Seed)
	}

	indexRaw, err := json.MarshalIndent(index, "", "  ")
	if err != nil {
		fatal(err)
	}
	if err := os.WriteFile(filepath.Join(*out, "index.json"), indexRaw, 0o644); err != nil {
		fatal(err)
	}
	fmt.Printf("schema v%d — %d clips, %d bytes total → %s\n",
		liveplay.TraceSchemaVersion, len(clips), total, *out)
}

func fatal(err error) {
	fmt.Fprintln(os.Stderr, "liveplaydemo:", err)
	os.Exit(1)
}
